public class Main {
    static int firstIndex(int[] a, int target) {
        int low = 0, high = a.length - 1, answer = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (a[mid] == target) {
                answer = mid;
                high = mid - 1;
            } else if (a[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    }

    public static void main(String[] args) {
        int[] a = {1, 2, 2, 2, 3, 5};
        System.out.println(firstIndex(a, 2));
        System.out.println(firstIndex(a, 4));
    }
}
